/**
 * Hand-authored mirror of the frozen wire contract.
 *
 * SOURCE OF TRUTH: `contracts/openapi.yaml` and
 * `contracts/websocket-envelopes.schema.json`. The canonical TypeScript for the
 * REST surface is GENERATED by `pnpm gen:api` into `src/api/generated/schema.ts`
 * (gitignored). These hand-authored types exist so the app type-checks BEFORE
 * `gen:api` has been run (the generated dir is not committed). When the two
 * disagree, the generated output — i.e. the contract — wins; update this file or
 * (better) re-export from the generated types.
 */

// --- REST: GET /health (HealthStatus) ---
export interface HealthStatus {
  status: 'ok';
  service: string;
  version: string;
}

// --- REST: GET /health/ready (ReadinessStatus) ---
export type ReadinessState = 'ready' | 'degraded';

export interface DependencyStatus {
  /** Dependency identifier (e.g. postgres, redis, minio). */
  name: string;
  ok: boolean;
  /** Optional human-readable detail when not ok. */
  detail?: string;
}

export interface ReadinessStatus {
  status: ReadinessState;
  dependencies: DependencyStatus[];
}

// --- Auth (contracts/openapi.yaml §auth, spec 0004 §2.3) ---

/** POST /auth/login body. `password` is write-only on the wire. */
export interface LoginRequest {
  email: string;
  password: string;
}

/** 200 from POST /auth/login and POST /auth/refresh. */
export interface TokenResponse {
  /** Short-lived JWT bearer token. */
  access_token: string;
  token_type: 'bearer';
  /** Access-token lifetime in seconds. */
  expires_in: number;
}

/** Tenant roles (MVP RBAC, spec 0004 §2.3). */
export type UserRole = 'member' | 'admin' | 'security';

/** 200 from GET /auth/me — the authenticated principal. */
export interface CurrentUser {
  id: string;
  email: string;
  /** Resolved from the bearer token; clients never send it (spec 0004). */
  tenant_id: string;
  /** Human-readable tenant name so the UI never surfaces the raw id (#247). */
  tenant_name: string;
  roles: UserRole[];
  created_at: string;
}

// --- Collections (contracts/openapi.yaml §collections) ---

/** POST /collections body. */
export interface CollectionCreate {
  name: string;
  description?: string;
}

/** PATCH /collections/{id} body — at least one property required (minProperties: 1). */
export interface CollectionUpdate {
  name?: string;
  description?: string;
}

/** A collection (folder grouping documents). */
export interface Collection {
  id: string;
  name: string;
  description?: string;
  owner_id: string;
  document_count: number;
  created_at: string;
  updated_at: string;
}

/** 200 from GET /collections — a cursor page of collections. */
export interface CollectionList {
  items: Collection[];
  /** Cursor for the next page, or null when exhausted. */
  next_cursor?: string | null;
}

// --- Documents (contracts/openapi.yaml §documents) ---

/** Ingestion lifecycle (parse → chunk → embed). */
export type DocumentStatus = 'pending' | 'processing' | 'ready' | 'failed';

/** A document's metadata, including its ingestion status. */
export interface Document {
  id: string;
  filename: string;
  mime_type: string;
  size_bytes: number;
  collection_id: string;
  owner_id: string;
  status: DocumentStatus;
  /** Failure reason when status is failed. */
  error?: string;
  /** Number of indexed chunks (0 until ingestion completes). */
  chunk_count: number;
  created_at: string;
  updated_at: string;
}

/** 200 from GET /documents — a cursor page of documents. */
export interface DocumentList {
  items: Document[];
  next_cursor?: string | null;
}

/** Query filters for GET /documents (collection / status / filename substring). */
export interface DocumentListQuery {
  collection_id?: string;
  status?: DocumentStatus;
  /** Filename substring (lexical, not semantic). */
  q?: string;
  cursor?: string;
  limit?: number;
}

// --- Shared error model: Problem (RFC-9457 application/problem+json) ---
export interface ProblemFieldError {
  field: string;
  message: string;
}

export interface Problem {
  /** URI identifying the problem type. Defaults to "about:blank". */
  type: string;
  /** Short, human-readable summary. */
  title: string;
  /** HTTP status code. */
  status: number;
  /** Human-readable explanation for this occurrence. */
  detail?: string;
  instance?: string;
  /** Stable, machine-readable error code for clients to branch on. */
  code?: string;
  /** Field-level validation errors, when applicable. */
  errors?: ProblemFieldError[];
}

// --- Chat (contracts/openapi.yaml §chat) ---

/** Picker grouping for chat models. */
export type ModelTier = 'frontier' | 'fast' | 'oss';

/** GET /models item — one selectable chat model. */
export interface ChatModelInfo {
  /** Model id passed to chat (e.g. anthropic/claude-opus-4.8). */
  id: string;
  /** Display name for the picker. */
  label: string;
  /** e.g. anthropic, openai, google, deepseek, qwen. */
  provider: string;
  tier: ModelTier;
  is_default: boolean;
  description?: string;
}

/** 200 from GET /models. */
export interface ModelList {
  items: ChatModelInfo[];
}

export type MessageRole = 'user' | 'assistant' | 'system';

/**
 * A clickable, passage-level reference (spec 0004 INV-3). Resolves to a document
 * the caller is permitted to see and a character span within it.
 */
export interface Citation {
  id: string;
  document_id: string;
  document_name: string;
  chunk_id: string;
  /** The cited passage text. */
  snippet: string;
  char_start: number;
  char_end: number;
  /** Optional retrieval/rerank score. */
  score?: number;
}

export interface Message {
  id: string;
  session_id: string;
  role: MessageRole;
  content: string;
  /** Model that produced an assistant message (absent for user). */
  model?: string;
  /** Passage-level citations (assistant messages only). */
  citations?: Citation[];
  created_at: string;
}

export interface MessageList {
  items: Message[];
  next_cursor?: string | null;
}

export interface ChatSession {
  id: string;
  title: string;
  /** The session's default model id. */
  model: string;
  owner_id: string;
  message_count: number;
  created_at: string;
  updated_at: string;
}

export interface ChatSessionList {
  items: ChatSession[];
  next_cursor?: string | null;
}

/** POST /chat/sessions body. */
export interface ChatSessionCreate {
  /**
   * Optional (additive; ADR-0011 §5). Start the session from an assistant: the
   * server resolves it, pins its current published version, and injects its
   * instructions / tool-allowlist / knowledge-scope into the chat runtime.
   * Omitted ⇒ an ad-hoc session. A cross-tenant / non-owned / non-granted id →
   * 404; a non-published or disabled assistant → 422.
   */
  assistant_id?: string;
  title?: string;
  /** A model id from GET /models; omitted = server default. */
  model?: string;
}

/** PATCH /chat/sessions/{id} body — at least one property. */
export interface ChatSessionUpdate {
  title?: string;
  model?: string;
}

/** POST /chat/sessions/{id}/messages body. */
export interface SendMessageRequest {
  content: string;
  /** Override the session model for this turn (a GET /models id). */
  model?: string;
  /** Restrict retrieval to these collections; omitted = all permitted docs. */
  collection_ids?: string[];
}

/** 202 from POST /chat/sessions/{id}/messages. */
export interface SendMessageResponse {
  /** The persisted user message. */
  message: Message;
  /** Subscribe to this WebSocket stream id for the assistant answer. */
  stream_id: string;
}

// --- Search (contracts/openapi.yaml §search, M2 #80) ---

/** Where a result originated (`connector` reserved; framework is post-MVP). */
export type ResultSource = 'upload' | 'chat' | 'connector';

/**
 * Per-result permission outcome. Trimmed results are normally `allowed`;
 * `restricted` is metadata-only (exists, but content withheld). Passages the
 * caller may not see at all are never returned — counted in `hidden_count`
 * (spec 0004 INV-2).
 */
export type PermissionState = 'allowed' | 'restricted';

/** A character span within a snippet that matched the query (for highlighting). */
export interface MatchSpan {
  start: number;
  end: number;
}

/** One permission-trimmed ranked search result (spec 0004 INV-1/INV-2). */
export interface SearchResult {
  id: string;
  title: string;
  /** Excerpt of the matched passage. */
  snippet: string;
  /** Character spans within `snippet` that matched the query. */
  match_spans: MatchSpan[];
  /** Human-readable explanation of why this result ranked. */
  why_matched: string;
  source: ResultSource;
  /** Content type of the result (e.g. document, message). */
  type: string;
  /** Owning principal id, when known (null for system/connector content). */
  owner?: string | null;
  /** Freshness — when this result was last indexed. */
  last_indexed: string;
  permission: PermissionState;
  /** Source document id when the result resolves to a document (click-through). */
  document_id?: string;
  /** Optional retrieval/rerank score. */
  score?: number;
}

/**
 * A citation backing the direct answer — references a passage present in this
 * response's `results` (by `result_id`), so an answer can never cite a passage
 * the caller could not retrieve (spec 0004 INV-3).
 */
export interface SearchCitation {
  /** Id of the SearchResult this citation refers to. */
  result_id: string;
  /** The specific cited passage text (a substring of the result snippet). */
  snippet?: string;
  char_start?: number;
  char_end?: number;
}

/**
 * An optional synthesized answer. Present only when the permitted results
 * support it; every claim is backed by `citations` (spec 0004 INV-3).
 */
export interface DirectAnswer {
  /** The synthesized answer (rendered as sanitized markdown). */
  text: string;
  citations: SearchCitation[];
}

/** 200 from GET /search — a page of permission-trimmed ranked results. */
export interface SearchResponse {
  /** The query that produced this page (echoed back). */
  query: string;
  results: SearchResult[];
  /** Optional cited answer; omitted when nothing permitted answers the query. */
  direct_answer?: DirectAnswer;
  /**
   * How many otherwise-matching results were withheld because they are outside
   * the caller's permissions (spec 0004 INV-2).
   */
  hidden_count: number;
  next_cursor?: string | null;
}

/** Query filters for GET /search (`q` required). */
export interface SearchQuery {
  q: string;
  collection_id?: string;
  source?: ResultSource;
  /** Restrict to one content type (e.g. document, message). */
  type?: string;
  cursor?: string;
  limit?: number;
}

// --- Audit (contracts/openapi.yaml §audit, M2 #80) ---

/** Audit event taxonomy (spec 0004 §2.4). */
export type AuditEventType =
  | 'auth.login'
  | 'auth.login_failed'
  | 'auth.logout'
  | 'collection.created'
  | 'document.uploaded'
  | 'document.viewed'
  | 'document.downloaded'
  | 'document.deleted'
  | 'retrieval.query'
  | 'answer.generated'
  | 'permission.denied'
  | 'action.requested'
  | 'action.approved'
  | 'action.executed';

/** The outcome recorded for an audit event (spec 0004 §2.4). */
export type AuditDecision = 'allowed' | 'denied' | 'error';

/** Whether a retrieval candidate was allowed into the result set or excluded. */
export type AuditCandidateDisposition = 'allow' | 'exclude';

/**
 * One retrieval candidate considered for a decision, and whether it was allowed
 * or excluded — with the reason. The provenance that makes a permission/answer
 * decision reviewable (spec 0004 §2.4).
 */
export interface AuditCandidate {
  resource_id: string;
  disposition: AuditCandidateDisposition;
  /** Why it was allowed or excluded (e.g. "in allow-set", "owner mismatch"). */
  reason: string;
  score?: number;
}

/** Why a decision was made — candidate dispositions plus the raw recorded payload. */
export interface AuditProvenance {
  candidates: AuditCandidate[];
  /** The raw recorded metadata payload (model id, query hash, etc.). */
  raw?: Record<string, unknown>;
}

/** One append-only audit event (spec 0004 §2.4). */
export interface AuditEvent {
  id: string;
  /** Event time (UTC ISO-8601). */
  ts: string;
  /** The acting principal — a user id, or `system` / `anonymous`. */
  actor: string;
  tenant_id: string;
  event_type: AuditEventType;
  /** The resource the event touched, when applicable. */
  resource_id?: string | null;
  decision: AuditDecision;
  provenance: AuditProvenance;
}

/** 200 from GET /audit — a cursor page of audit events (newest → oldest). */
export interface AuditEventList {
  items: AuditEvent[];
  next_cursor?: string | null;
}

/** Query filters for GET /audit (admin / security only). */
export interface AuditQuery {
  /** One actor (user id, or `system`/`anonymous`). */
  actor?: string;
  event_type?: AuditEventType;
  resource_id?: string;
  /** Inclusive lower bound on event timestamp (UTC ISO-8601). */
  from?: string;
  /** Exclusive upper bound on event timestamp (UTC ISO-8601). */
  to?: string;
  cursor?: string;
  limit?: number;
}

// --- Admin (contracts/openapi.yaml §admin, M2 #80) ---

/** A tenant member and their role(s) for the admin roster. */
export interface Member {
  id: string;
  email: string;
  /** The member's tenant roles (MVP RBAC, spec 0004 §2.3). */
  role: UserRole[];
}

/** 200 from GET /admin/members — a cursor page of members. */
export interface MemberList {
  items: Member[];
  next_cursor?: string | null;
}

/** One allowed model and the governance tier it maps to. */
export interface ModelGovernanceEntry {
  /** A model id (e.g. anthropic/claude-opus-4.8). */
  model_id: string;
  /** The governance tier this model is approved at. */
  tier: string;
  /** Display name for the admin console. */
  label?: string;
}

/** A governance tier referenced by allowed models. */
export interface ModelGovernanceTier {
  id: string;
  description: string;
}

/** 200 from GET /admin/model-governance — read-only model governance. */
export interface ModelGovernance {
  allowed_models: ModelGovernanceEntry[];
  tiers: ModelGovernanceTier[];
}

/** Read-before-write tier identifiers (spec 0004 §2.5). */
export type RiskTierId = 'T0' | 'T1' | 'T2' | 'T3';

/** One read-before-write risk tier (spec 0004 §2.5). */
export interface RiskTier {
  tier: RiskTierId;
  /** What this tier means / example actions. */
  description: string;
  /** The approval this tier requires. */
  approval: string;
}

/** 200 from GET /admin/risk-tiers — the risk-tier reference (T0–T3). */
export interface RiskTierList {
  items: RiskTier[];
}

// --- Sources (contracts/openapi.yaml §sources, ADR-0009 / #108) ---

/**
 * The connector kind. `web` is the first connector (ADR-0009 §2): paste a public
 * URL, we ingest it — zero source-side setup. Future connectors add their own
 * values here, each behind its own ADR.
 */
export type SourceType = 'web';

/**
 * How a `web` source's URL is interpreted (ADR-0009 §2). `page` = one URL → one
 * document; `feed` = an RSS/Atom feed → many; `sitemap` = a sitemap.xml → many.
 * The server detects the mode from the fetched content.
 */
export type WebSourceMode = 'page' | 'feed' | 'sitemap';

/**
 * Sync lifecycle for the connector health grid (ADR-0009 §4). `pending` = added,
 * not yet synced; `syncing` = a sync is in flight; `ready` = last sync succeeded;
 * `error` = the last sync failed (see `last_error`).
 */
export type SourceStatus = 'pending' | 'syncing' | 'ready' | 'error';

/** Connector configuration. For the `web` connector: the fetched url + detected mode. */
export interface SourceConfig {
  /** The public URL this source ingests (http/https only; SSRF-checked). */
  url: string;
  mode: WebSourceMode;
}

/**
 * One connected source, tenant- and owner-scoped (ADR-0009 §4/§5, spec 0004
 * INV-1/INV-2). Ingested content is retrievable only by the owner within tenant.
 */
export interface Source {
  id: string;
  type: SourceType;
  config: SourceConfig;
  status: SourceStatus;
  /** Documents this source has ingested (0 until the first sync completes). */
  indexed_count: number;
  /** When the last successful sync finished (null before the first sync). */
  last_synced_at?: string | null;
  /** Failure reason when status is error. */
  last_error?: string;
  owner_id: string;
  created_at: string;
  updated_at: string;
}

/** 200 from GET /sources — a cursor page of sources. */
export interface SourceList {
  items: Source[];
  next_cursor?: string | null;
}

/**
 * POST /sources body. For the `web` connector: `{type: 'web', url}`. The server
 * validates + SSRF-checks the URL; an invalid or blocked URL → 422 (INV-8,
 * ADR-0009 §3).
 */
export interface SourceCreate {
  type: SourceType;
  /** The public URL to ingest (http/https only). */
  url: string;
}

// --- Assistants (contracts/openapi.yaml §assistants, ADR-0011 / #210) ---

/**
 * How much an assistant may act on its own (ADR-0011 §3). Capped by the risk
 * tier of its allowed tools; at MVP the product is T0/T1 only.
 */
export type AutonomyLevel = 'suggest' | 'draft' | 'act_with_approval' | 'act_auto';

/** Lifecycle status (ADR-0011 §1). A disabled assistant cannot start new sessions. */
export type AssistantStatus = 'draft' | 'published' | 'disabled';

/** A retrieval source class the assistant's scope may draw from. */
export type KnowledgeMode = 'company' | 'uploaded' | 'web' | 'model';

/**
 * The retrieval filter (ADR-0011 §1/§2). A *narrowing* set layered on top of the
 * per-user INV-2 permission predicate inside `retrieval/` — it can only
 * intersect, never widen, what the running principal may already retrieve.
 */
export interface KnowledgeScope {
  /** Collections to scope retrieval to (empty ⇒ no collection narrowing). */
  collectionIds?: string[];
  /** Connected sources to scope retrieval to. */
  sourceIds?: string[];
  /** Which source classes the scope may draw from. */
  modes?: KnowledgeMode[];
}

/**
 * A saved, named, governed chat configuration (ADR-0011 §1) — the mutable head.
 * Tenant- and owner-scoped (INV-1/INV-2).
 */
export interface Assistant {
  id: string;
  name: string;
  /** Optional human description. */
  description?: string | null;
  /** System-prompt text injected at run time (persona/role; never removes grounding rules). */
  instructions?: string | null;
  /** A model id from GET /models; null ⇒ the smart server default resolved at run time. */
  model: string | null;
  knowledgeScope: KnowledgeScope;
  /** Tool names the run may use ([] ⇒ the default retrieval tool set until CC-A lands). */
  toolAllowlist: string[];
  autonomyLevel: AutonomyLevel;
  /** The accountable owner's user id. */
  owner: string;
  /** The backup owner's user id; required before publish (ADR-0011 §4). */
  backupOwner?: string | null;
  status: AssistantStatus;
  /** The current published head version number (null while never published). */
  version?: number | null;
  created_at: string;
  updated_at: string;
}

/**
 * POST /assistants body — create a draft (ADR-0011 §1). Only `name` is required;
 * the server owns `owner`/`status`/timestamps. A malformed body → 422 (INV-8).
 */
export interface AssistantCreate {
  name: string;
  description?: string;
  instructions?: string;
  /** A model id from GET /models; omitted ⇒ the smart server default. */
  model?: string;
  knowledgeScope?: KnowledgeScope;
  toolAllowlist?: string[];
  autonomyLevel?: AutonomyLevel;
  /** Optional at draft time; required before publish. */
  backupOwner?: string;
}

/**
 * PATCH /assistants/{id} body — patch the mutable head (ADR-0011 §1). All fields
 * optional; at least one must be present (minProperties: 1). Malformed → 422.
 */
export interface AssistantUpdate {
  name?: string;
  description?: string | null;
  instructions?: string | null;
  /** A model id from GET /models, or null to clear (⇒ smart server default). */
  model?: string | null;
  knowledgeScope?: KnowledgeScope;
  toolAllowlist?: string[];
  autonomyLevel?: AutonomyLevel;
  /** Set or clear the backup owner (must be distinct from owner, same tenant). */
  backupOwner?: string | null;
}

/** The full frozen assistant definition captured at publish time (ADR-0011 §1). */
export interface AssistantVersionConfig {
  name: string;
  description?: string | null;
  instructions?: string | null;
  model: string | null;
  knowledgeScope: KnowledgeScope;
  toolAllowlist: string[];
  autonomyLevel: AutonomyLevel;
}

/**
 * An immutable published snapshot (ADR-0011 §1) — the full frozen definition a
 * session/run pins to. Write-once; never mutated or deleted.
 */
export interface AssistantVersion {
  id: string;
  assistant_id: string;
  /** Monotonic per assistant (unique within the assistant). */
  version: number;
  config: AssistantVersionConfig;
  /** The user id who published (or rolled back to create) this version. */
  author: string;
  notes?: string | null;
  diff_summary?: string | null;
  created_at: string;
}

/** Optional release metadata for a publish (ADR-0011 §1). */
export interface AssistantPublishRequest {
  notes?: string;
}

/** Roll the head back to a prior version (ADR-0011 §1). Unknown/malformed → 422. */
export interface AssistantRollbackRequest {
  version: number;
  notes?: string;
}

/** 200 from GET /assistants — a cursor page of assistants. */
export interface AssistantList {
  items: Assistant[];
  next_cursor?: string | null;
}

/** 200 from GET /assistants/{id}/versions — a cursor page of versions. */
export interface AssistantVersionList {
  items: AssistantVersion[];
  next_cursor?: string | null;
}

// --- Schedules & runs (contracts/openapi.yaml §schedules, §runs; ADR-0015) ---
// Hand-authored mirror of the FROZEN contract (frontend/AGENTS.md: `api/types.ts`
// is the documented stopgap; the generated `schema.ts` is gitignored). Kept in
// lock-step with `pnpm gen:api` — the contract wins.

/** The recurrence period for a structured cadence (ADR-0015 §2). */
export type CadenceUnit = 'hour' | 'day' | 'week' | 'month';

/**
 * A structured recurrence — the human-friendly alternative to a raw cron
 * expression (ADR-0015 §2). e.g. `{ every: 'day', at: '08:00' }` = every day at
 * 08:00 local (in the schedule's `timezone`). `day_of_week` (0=Sunday..6=Saturday)
 * applies when `every` is `week`; `day_of_month` (1..31) when `every` is `month`.
 */
export interface StructuredCadence {
  every: CadenceUnit;
  /** Local time-of-day HH:MM (24h) in the schedule's timezone. */
  at: string;
  /** 0=Sunday..6=Saturday; used when `every` is `week`. */
  day_of_week?: number | null;
  /** 1..31; used when `every` is `month`. */
  day_of_month?: number | null;
}

/**
 * A schedule's recurrence — exactly one form (ADR-0015 §2): either a raw `cron`
 * expression OR a `StructuredCadence`. The server normalizes both to one stored
 * form and computes `next_run_at` tz/DST-correct. A malformed cron is a 422
 * (`invalid_cron`).
 */
export type Cadence = { cron: string } | { structured: StructuredCadence };

/** In-app digest cadence for a schedule's delivery, or none. */
export type ScheduleDigest = 'none' | 'daily' | 'weekly' | null;

/**
 * Where a completed run's result lands (ADR-0015 §6). v1 is in-app only — the run
 * inbox and an optional digest; external channels (email/Slack) are deferred.
 */
export interface ScheduleDelivery {
  /** Land the completed run in the owner's in-app run inbox (default true). */
  inbox: boolean;
  /** Roll recent runs into a periodic in-app digest, or null/none for no digest. */
  digest?: ScheduleDigest;
}

/**
 * What happens when a schedule fires while its previous run is still active
 * (ADR-0015 §5). `skip` (default) records a skipped fire; `queue` enqueues behind
 * the active run; `allow` runs concurrently.
 */
export type OverlapPolicy = 'skip' | 'queue' | 'allow';

/**
 * The run state machine (ADR-0015 §2). Terminal states are `succeeded`, `failed`,
 * and `escalated` (a first-class terminal, distinct from failed — the run needs a
 * human). An illegal transition is a 409 (INV-8).
 */
export type RunStatus = 'queued' | 'running' | 'succeeded' | 'failed' | 'escalated';

/** Why the run fired (ADR-0015 §2). `schedule` = a cadence fire; `manual` = run-now. */
export type RunTrigger = 'schedule' | 'manual';

/**
 * A user-defined recurring run of a saved assistant, tenant- and owner-scoped
 * (ADR-0015 §2/§8, INV-1/INV-2). The `owner_id` is the run's principal — a fired
 * run retrieves only what the owner could retrieve interactively (INV-2).
 */
export interface Schedule {
  id: string;
  /** The saved assistant this schedule runs. */
  assistant_id: string;
  /** The schedule's owner — the run's principal (INV-2). */
  owner_id: string;
  cadence: Cadence;
  /** IANA timezone name (e.g. America/New_York); drives DST-correct next_run_at. */
  timezone: string;
  /** The assistant's inputs applied to each fire (the prompt-template values). */
  input_params?: Record<string, unknown>;
  delivery: ScheduleDelivery;
  overlap_policy: OverlapPolicy;
  /** True = firing; false = paused (the derived RedBeat entry is removed). */
  enabled: boolean;
  /** The upcoming fire (computed tz/DST-correct); null when paused. */
  next_run_at?: string | null;
  /** When this schedule last fired, or null before the first fire. */
  last_run_at?: string | null;
  /** The status of the last fire, or null before the first fire. */
  last_status?: RunStatus | null;
  created_at: string;
  updated_at: string;
}

/**
 * POST /schedules body — create a recurring run (ADR-0015 §8). An invalid cron or
 * unknown IANA timezone is 422 (`invalid_cron` / `invalid_timezone`, INV-8); an
 * unknown assistant is 404 (INV-1/INV-2).
 */
export interface ScheduleCreate {
  assistant_id: string;
  cadence: Cadence;
  /** IANA timezone name (e.g. America/New_York). An unknown name is 422. */
  timezone: string;
  input_params?: Record<string, unknown>;
  delivery?: ScheduleDelivery;
  /** Overlap handling; omitted defaults to skip. */
  overlap_policy?: OverlapPolicy;
  /** Create paused by setting false; omitted defaults to true. */
  enabled?: boolean;
}

/**
 * PATCH /schedules/{id} body — edit a schedule (ADR-0015 §8). All fields optional;
 * at least one must be present (minProperties: 1). Any invalid cron / IANA
 * timezone is 422.
 */
export interface ScheduleUpdate {
  cadence?: Cadence;
  timezone?: string;
  input_params?: Record<string, unknown>;
  delivery?: ScheduleDelivery;
  overlap_policy?: OverlapPolicy;
  enabled?: boolean;
}

/** 200 from GET /schedules — a cursor page of the caller's schedules. */
export interface ScheduleList {
  items: Schedule[];
  next_cursor?: string | null;
}

/** 202 from POST /schedules/{id}/run-now — the id of the just-enqueued run. */
export interface RunEnqueued {
  /** The new run's id — also its WS streamId for live attach (ADR-0015 §3). */
  run_id: string;
}

/**
 * A typed run failure / escalation reason (ADR-0015 §2) — never a raw vendor
 * string. Present on `failed` and `escalated` runs.
 */
export interface RunError {
  /** Stable machine-readable reason (e.g. model_unavailable, ambiguous, tool_failed). */
  code: string;
  /** Human-readable explanation for the owner's inbox. */
  message: string;
}

/**
 * A transcript step kind (ADR-0015 §2) — the durable analogue of the WS envelope
 * type set: `delta` (incremental output), `tool_call` / `tool_result` (a tool
 * turn), `citation` (a grounded passage), `error` (a failure step).
 */
export type RunStepKind = 'delta' | 'tool_call' | 'tool_result' | 'citation' | 'error';

/**
 * One ordered step of a run's persisted transcript (ADR-0015 §2), the durable
 * equivalent of a WS envelope. `seq` is monotonic per run. `payload` carries the
 * envelope `data` (tool args/results, delta text, or citation fields), typed per
 * `kind`.
 */
export interface RunStep {
  /** Monotonic per-run sequence — the transcript ordering (matches the WS seq). */
  seq: number;
  kind: RunStepKind;
  /** The step data (the envelope `data`), typed per `kind`. */
  payload?: Record<string, unknown>;
  created_at: string;
}

/**
 * One execution of an assistant — scheduled or manual (ADR-0015 §2/§8), tenant-
 * and owner-scoped (INV-1/INV-2). The full detail carries the ordered transcript
 * (`steps`), the grounded `citations` (permitted, retrieved passages only —
 * INV-3), the `outputs`, and the typed `error` on a failed/escalated run. `id`
 * doubles as the WS `streamId` for live attach (ADR-0015 §3).
 */
export interface Run {
  /** The run id — also its WS streamId for live attach (ADR-0015 §3). */
  id: string;
  /** The schedule that fired this run, or null for a manual/run-now run. */
  schedule_id?: string | null;
  assistant_id: string;
  /** The pinned assistant version executed — a run is reproducible after edits. */
  assistant_version_id?: string | null;
  trigger: RunTrigger;
  status: RunStatus;
  /** The resolved input_params snapshotted for this fire. */
  inputs?: Record<string, unknown>;
  /** Short digest line for the inbox (ADR-0015 §6). */
  summary?: string | null;
  /** The assistant message the transcript produced (reuses chat message/citation tables). */
  message_id?: string | null;
  /** The ordered persisted transcript (empty on the list view; present on detail). */
  steps?: RunStep[];
  /** The grounded citations of the run's answer — permitted passages only (INV-3). */
  citations?: Citation[];
  /** The run's structured outputs, when the assistant produces them. */
  outputs?: Record<string, unknown>;
  /** The typed failure / escalation reason on a failed or escalated run; else null. */
  error?: RunError | null;
  /** When the run started executing, or null while queued. */
  started_at?: string | null;
  /** When the run reached a terminal status, or null while not terminal. */
  finished_at?: string | null;
  created_at: string;
}

/** 200 from GET /runs — a cursor page of runs (newest first). */
export interface RunList {
  items: Run[];
  next_cursor?: string | null;
}

// --- WebSocket envelopes (contracts/websocket-envelopes.schema.json) ---
// Lifecycle: start -> (delta | event)* -> done | error, exactly one terminal.
export type EnvelopeType = 'start' | 'delta' | 'event' | 'done' | 'error';

interface BaseEnvelope {
  type: EnvelopeType;
  /** Correlates all messages of one logical stream. */
  streamId: string;
  /** Monotonically increasing per streamId; defines ordering. */
  seq: number;
  /** Server send time (optional, ISO-8601). */
  ts?: string;
}

export interface StartEnvelope extends BaseEnvelope {
  type: 'start';
  /** Stream-open metadata; shape defined per feature. */
  data?: Record<string, unknown>;
}

export interface DeltaEnvelope extends BaseEnvelope {
  type: 'delta';
  /** Incremental output (e.g. a token chunk). Payload shape defined per feature. */
  data: unknown;
}

export interface EventEnvelope extends BaseEnvelope {
  type: 'event';
  /** Structured side-band event name (e.g. citation, tool_call). */
  name: string;
  data?: unknown;
}

export interface DoneEnvelope extends BaseEnvelope {
  type: 'done';
  /** Terminal success summary; shape defined per feature. */
  data?: Record<string, unknown>;
}

/** Subset of Problem carried on a WS error envelope (title + status required). */
export interface WsProblem {
  title: string;
  status: number;
  detail?: string;
  code?: string;
}

export interface ErrorEnvelope extends BaseEnvelope {
  type: 'error';
  problem: WsProblem;
}

export type WsEnvelope =
  | StartEnvelope
  | DeltaEnvelope
  | EventEnvelope
  | DoneEnvelope
  | ErrorEnvelope;

/** A terminal envelope ends a stream (exactly one per streamId). */
export type TerminalEnvelope = DoneEnvelope | ErrorEnvelope;

// --- Chat answer-stream payloads (websocket-envelopes.schema.json x-chatStream) ---
// These slot into the generic envelope `data`/`event` shapes for a chat answer:
//   start(ChatStartData) -> ( delta(ChatTokenDelta) | event:tool_call(ChatToolCall)
//     | event:tool_result(ChatToolResult) | event:citation(ChatCitation) )*
//   -> done(ChatDoneData) | error(Problem)

/** `start.data` for a chat answer stream. */
export interface ChatStartData {
  sessionId: string;
  /** Id the in-progress assistant message will be persisted under. */
  messageId: string;
  /** Model id producing this answer. */
  model: string;
}

/** `delta.data` — one streamed chunk of the assistant answer. */
export interface ChatTokenDelta {
  text: string;
}

/**
 * `event.data` for name=citation. Mirrors the REST Citation (spec 0004 INV-3) but
 * camelCased per the WS envelope schema. Rendered as a clickable reference
 * resolving to the document + span.
 */
export interface ChatCitation {
  id: string;
  documentId: string;
  documentName: string;
  chunkId: string;
  snippet: string;
  charStart: number;
  charEnd: number;
  score?: number;
}

/** Retrieval tool the chat agent can invoke (surfaced for "searching…" UX). */
export type ChatTool = 'search_text' | 'search_documents' | 'get_document';

/** `event.data` for name=tool_call — the agent invoked a retrieval tool. */
export interface ChatToolCall {
  callId: string;
  tool: ChatTool;
  args: Record<string, unknown>;
}

/** `event.data` for name=tool_result — outcome of a tool_call. */
export interface ChatToolResult {
  callId: string;
  tool: ChatTool;
  hitCount: number;
  summary?: string;
}

/** `done.data` — terminal success summary for a chat answer. */
export interface ChatDoneData {
  messageId: string;
  /** e.g. stop, length, content_filter. */
  finishReason: string;
  citationCount: number;
  usage?: {
    promptTokens?: number;
    completionTokens?: number;
    totalTokens?: number;
  };
}

// --- Preferences / saved searches / suggestions (spec 0005, epic #144) ------

/** `GET`/`PATCH /preferences` response — the caller's account preferences. */
export interface UserPreferences {
  /** A `/models` id, or null to use the server default. */
  default_model_id: string | null;
  /** When last changed, or null if never (the implicit server-default state). */
  updated_at: string | null;
}

/** `PATCH /preferences` body — partial (at least one field). */
export interface UserPreferencesUpdate {
  /** A `/models` id to set, or null to clear (fall back to the server default). */
  default_model_id?: string | null;
}

/** A saved `/search` query + its filters. */
export interface SavedSearch {
  id: string;
  name: string;
  query: string;
  collection_id?: string | null;
  source?: ResultSource | null;
  type?: string | null;
  owner_id: string;
  created_at: string;
  updated_at: string;
}

/** `POST /saved-searches` body. */
export interface SavedSearchCreate {
  name: string;
  query: string;
  collection_id?: string;
  source?: ResultSource;
  type?: string;
}

/** `PATCH /saved-searches/{id}` body — partial (at least one field). */
export interface SavedSearchUpdate {
  name?: string;
  query?: string;
  collection_id?: string | null;
  source?: ResultSource | null;
  type?: string | null;
}

/** `GET /saved-searches` response (cursor-paginated). */
export interface SavedSearchList {
  items: SavedSearch[];
  next_cursor?: string | null;
}

/** What a typeahead suggestion represents. */
export type SuggestionKind = 'completion' | 'document' | 'saved_search';

/** One typeahead suggestion from `GET /search/suggest`. */
export interface Suggestion {
  kind: SuggestionKind;
  text: string;
  document_id?: string | null;
  source?: ResultSource | null;
  saved_search_id?: string | null;
}

/** `GET /search/suggest` response. */
export interface SuggestResponse {
  suggestions: Suggestion[];
}

/** One recent `/search` query the caller ran. */
export interface RecentSearch {
  query: string;
  last_used_at: string;
}

/** `GET /search/recent` response. */
export interface RecentSearchList {
  items: RecentSearch[];
}
